import {installVoice} from './voice-local.js';
import {velocity,acceleration,position,motion,grade,KEY,initial,valid,viewpoints,makeAnswer} from './model.js';
const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lang='en';
let s=initial(),blocked=false,storageIssue=false,lastRaw=null,ephemeral={direction:'',speed:''};
try{lastRaw=localStorage.getItem(KEY);if(lastRaw){const parsed=JSON.parse(lastRaw);if(!valid(parsed))throw Error();s=parsed;}}catch{blocked=true;storageIssue=true;}
const L=en=>en;
function status(){ $('saveStatus').textContent=blocked?L('Local record unavailable or changed elsewhere. Download notes before leaving.'):storageIssue?L('Could not save. Download notes before leaving.'):L('Saved in this browser');$('saveStatus').classList.toggle('error',blocked||storageIssue);}
function save(){if(!blocked)try{const current=localStorage.getItem(KEY);if(current!==lastRaw){blocked=true;}else{const raw=JSON.stringify(s);localStorage.setItem(KEY,raw);lastRaw=raw;storageIssue=false;}}catch{storageIssue=true;}status();}
window.addEventListener('storage',e=>{if(e.key===KEY||e.key===null){blocked=true;status();}});
const claimLabel=c=>({custom:L('I have my own version.'),yes:L('Positive acceleration always means moving forward.'),no:L('Not necessarily; velocity also matters.'),unsure:L('I’m not sure yet. I’d like to test it.')}[c]||'');
function bubble(text){return `<div class="bubble"><span class="speaker">Q / QUIDENCE</span><p>${text}</p></div>`;}
function quote(text){return `<div class="quote">${esc(text)}</div>`;}
function button(id,text,cls='primary'){const mark={begin:'↗',probe:'→',check:'→',hint:'?',focus:'⌖',next:'→',download:'↓',revisit:'↺'}[id];return `<button id="${id}" class="${cls}">${mark?`<span class="action-mark" aria-hidden="true">${mark}</span>`:''}<span>${text}</span></button>`;}
function field(id,label,value='',hint=''){return `<label class="field" for="${id}">${label}</label>${hint?`<p id="${id}-hint" class="small">${esc(hint)}</p>`:''}<textarea id="${id}" maxlength="2000"${hint?` aria-describedby="${id}-hint"`:''}>${esc(value)}</textarea>`;}
function bindText(id,key){$(id).addEventListener('input',e=>{s[key]=e.target.value;save();});}
function advance(n){s.stage=n;ephemeral={direction:'',speed:''};save();render();$('conversationTitle').scrollIntoView({behavior:'auto',block:'start'});}
function translation(){document.documentElement.lang='en';document.querySelectorAll('[data-en]').forEach(e=>{e.innerHTML=e.dataset.en;});}
function graph(){const transfer=s.stage===3,t=s.t, X=t=>55+t*100,Y=v=>260-v*23;let path='';for(let i=0;i<=100;i++){const x=i/20,v=transfer?4-x:velocity(x);path+=`${i?'L':'M'}${X(x)},${Y(v)} `;}let content=`<title id="graphTitle">${L('Velocity over time')}</title><desc id="graphDescription">${esc(L('Time from 0 to 5 minutes; velocity in m/s.'))}</desc>`;
for(let v=-2;v<=8;v+=2)content+=`<line x1="55" x2="555" y1="${Y(v)}" y2="${Y(v)}" stroke="${v===0?'#899d9d':'#e8edec'}" ${v===0?'':'stroke-dasharray="3 5"'}/><text x="42" y="${Y(v)+4}" text-anchor="end" font-size="11" fill="#617578">${v}</text>`;
for(let i=0;i<=5;i++)content+=`<text x="${X(i)}" y="316" text-anchor="middle" font-size="11" fill="#617578">${i}</text>`;
const m=motion(t,transfer);content+=`<text x="55" y="18" font-size="11" fill="#617578">v (m/s)</text><text x="580" y="284" text-anchor="end" font-size="11" fill="#617578">t (min)</text><path d="${path}" fill="none" stroke="#153f44" stroke-width="3.5"/><line x1="${X(t)}" x2="${X(t)}" y1="32" y2="300" stroke="#dc795e" stroke-dasharray="4 5"/><circle cx="${X(t)}" cy="${Y(m.v)}" r="8" fill="#dc795e" stroke="white" stroke-width="3"/>`;
$('graph').innerHTML=content;$('time').value=t;$('timeOut').textContent=`${t.toFixed(2)} min`;$('velocity').textContent=m.v.toFixed(2);$('acceleration').textContent=m.a.toFixed(4);$('modelName').textContent=transfer?'02 / TRANSFER':'01 / RIDE';$('modelDesc').textContent=transfer?L('A new ride: v(t) = 4 − t, 0 ≤ t ≤ 5.'):L('Velocity model: v(t) = (t − 2)(t − 4), 0 ≤ t ≤ 5.');
const p=transfer?60*(4*t-t*t/2):position(t),px=55+p/500*500;$('track').innerHTML=`<line x1="55" x2="555" y1="24" y2="24" stroke="#c9d8d3" stroke-width="3"/><circle cx="${px}" cy="24" r="10" fill="#153f44"/><text x="55" y="55" font-size="12" fill="#617578">0 m</text><text x="555" y="55" text-anchor="end" font-size="12" fill="#617578">500 m</text>`;$('trackNote').textContent=L(`Position from the start: ${p.toFixed(1)} m. The dot shows position, not direction.`);$('capture').disabled=transfer||s.samples.length>=20;$('capture').textContent=transfer?L('New model for transfer; original evidence stays below'):s.samples.length>=20?L('20 moments saved'):L('＋ Keep this moment as a clue');
}
function samples(){ $('samples').innerHTML=s.samples.map((x,i)=>`<div class="sample"><button data-sample="${i}">${x.t.toFixed(2)} min</button> · v = ${velocity(x.t).toFixed(2)} m/s · a = ${acceleration(x.t).toFixed(4)} m/s² <label class="field" for="note${i}">${L('What caught your attention here? (optional)')}</label><textarea id="note${i}" maxlength="2000">${esc(x.note)}</textarea></div>`).join('');s.samples.forEach((x,i)=>{$(`note${i}`).oninput=e=>{x.note=e.target.value;save();};});document.querySelectorAll('[data-sample]').forEach(b=>{b.disabled=s.stage===3;b.onclick=()=>{s.t=s.samples[+b.dataset.sample].t;save();graph();};});}
function evidenceAt(t){const m=motion(t);return `<div class="evidence"><p>${L('Your selected evidence')}: t = ${t.toFixed(2)} min</p><p>v = ${m.v.toFixed(2)} m/s · a = ${m.a.toFixed(4)} m/s²</p></div>`;}
function correction(){return `<details><summary class="quiet">${L('That’s not what I meant / add context')}</summary>${field('correction',L('Add context. Both versions are kept, without automatic grading.'),s.correction)}</details>`;}
function checkForm(kind){const a=s[kind],pick=a?.mode==='custom'?'custom':a?.pick||s[kind+'Pick']||'';return `<p class="invitation">${L('Here are three viewpoints. None may fit. Choose one and explain why, or write your own version.')}</p><div class="choices" role="group" aria-label="${L('Three viewpoints')}">${viewpoints[kind].map((p,i)=>`<button class="choice ${pick===p.id?'selected':''}" data-view="${p.id}" aria-pressed="${pick===p.id}" ${a?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(p[lang])}</span></button>`).join('')}</div><div class="own-answer ${pick==='custom'?'selected':''}"><button id="ownAnswer" class="own-toggle" aria-pressed="${pick==='custom'}" ${a?'disabled':''}>${L('✎ I have my own version')}</button>${field('reason',pick==='custom'?L('My answer and reasoning'):L('Why do you think so? You can also say what the option leaves out. (optional)'),a?a.reason:s[kind+'Draft'],pick==='custom'?L('I think… because on the graph…'):L('Use the option as a starting point, then add your own thinking.'))}</div><p class="not-scored">${L('Writing your own answer is not marked wrong. This prototype checks only the numerical claims in preset viewpoints; your wording is kept for discussion.')}</p><div class="actions">${button('check',L('Try my idea'))}${button('hint',L('A clue, please'),'quiet')}</div><div id="hintArea">${s.hints.includes(kind)?hintText(kind):''}</div><div id="answerFeedback">${a?feedback(kind,a):''}</div>`;}
function hintText(kind){return `<div class="hint">${L('Direction follows the sign of velocity; speed is |v|. Is velocity moving toward zero or farther away?')}</div>`;}
function answerName(a){if(a.mode==='custom')return L('My own version (not automatically graded)');const dir={forward:L('forward'),backward:L('backward'),still:L('instantly at rest'),unsure:L('unsure')},speed={faster:L('speed increasing'),slower:L('speed decreasing'),instant:L('zero instantaneous rate'),unsure:L('unsure')};return `${dir[a.direction]} / ${speed[a.speed]}`;}
function feedback(kind,a){const tr=kind==='transfer',g=grade(a,tr?3:3.5,tr),own=a.mode==='custom';return `<div class="evidence ${!own&&(!g.direction||!g.speed)?'warning':''}"><p>${L('Your recorded thinking')}: ${answerName(a)}</p>${own?`<p>${L('Your words are preserved. This answer is not automatically graded; let’s look for evidence on the graph.')}</p>${quote(a.reason)}`:`<p>${L('Direction')}: ${g.direction?L('matches the model'):L('needs another look')} · ${L('Speed change')}: ${g.speed?L('matches the model'):L('needs another look')}</p>`}<p>${a.hinted?L('A hint was viewed before this answer.'):L('No hint for this question was opened before this answer.')}</p></div>${bubble(own?L('Which point or change on the graph best supports what you just wrote? Move the slider, then add a sentence.'):g.direction&&g.speed?L('The direction and speed change match the model. Which clue on the graph would you use to explain it to someone who chose differently?'):L('You do not have to keep the original wording. Keep the part you find reasonable and rewrite what needs changing. How would you put it?'))}${field('revision',L('Add evidence, revise, or leave a question (optional; your first answer stays)'),s[kind+'Revision']||'')}<details id="worked"><summary class="quiet">${L('Show me an explanation')}</summary><p class="hint">${tr?L('At t = 3, v = 1 > 0: forward. a = −1/60 < 0: velocity approaches zero, so speed decreases. None of the three preset viewpoints is fully correct. A better version is “moving forward, but slowing down.”'):L('At t = 3.5, v = −0.75 < 0: backward. a = 1/60 > 0: velocity approaches zero, so speed decreases. Positive acceleration does not guarantee forward motion.')}</p></details><div class="actions">${button('next',tr?L('See my field notes'):L('Try a fresh ride'))}</div>`;}
function bindCheck(kind){const a=s[kind];let pick=s[kind+'Pick']||'';const update=()=>{$('check').disabled=!!a||!pick||(pick==='custom'&&!s[kind+'Draft'].trim());};$('reason').disabled=!!a;$('reason').oninput=e=>{s[kind+'Draft']=e.target.value;save();update();};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{s[kind+'Pick']=b.dataset.view;save();render();});$('ownAnswer').onclick=()=>{s[kind+'Pick']='custom';save();render();$('reason').focus();};update();$('hint').onclick=()=>{if(!s.hints.includes(kind))s.hints.push(kind);save();$('hintArea').innerHTML=hintText(kind);};$('check').onclick=()=>{s[kind]=makeAnswer(kind,pick,s[kind+'Draft'],s.hints.includes(kind));save();render();};if(a){bindText('revision',kind+'Revision');$('next').onclick=()=>{if(kind==='challenge'){s.t=3;advance(3);}else advance(4);};$('worked').ontoggle=e=>{if(e.target.open&&!s.hints.includes(kind)){s.hints.push(kind);save();}};}}
function render(){voice.cancelReview();translation();const labels=[L('Your idea'),L('Find evidence'),L('Test the claim'),L('Try a new case'),L('Reflect')];$('progress').innerHTML=labels.map((t,i)=>`<div class="step ${s.stage===i?'active':s.stage>i?'done':''}" ${s.stage===i?'aria-current="step"':''}><b>${s.stage>i?'✓':String(i+1).padStart(2,'0')}</b>${t}</div>`).join('');$('conversationTitle').textContent=labels[s.stage];let html='';
if(s.stage===0){html=bubble(L('Someone says: “Acceleration is positive, so the rider must be moving forward.” What do you think?'))+`<div class="choices">${['yes','no','unsure'].map(c=>`<button class="choice ${s.claim===c?'selected':''}" data-claim="${c}" aria-pressed="${s.claim===c}">${claimLabel(c)}</button>`).join('')}</div>`+`<div class="own-answer ${s.claim==='custom'?'selected':''}">${button('initialOwn',L('✎ I have my own version'),'own-toggle')}${field('draft',s.claim==='custom'?L('My answer and reasoning'):L('Tell me why (optional)'),s.draft,L('It’s fine to say what you’re unsure about.'))}</div>`+`<p class="small">${L('Choose a view and explain, or switch to your own version. The prototype will not guess your stance from your wording.')}</p><div class="actions">${button('begin',L('Let’s follow the graph'))}</div>`;}
if(s.stage===1){html=`<span class="mini-label">${L('YOUR CONFIRMED VIEW')}</span>${quote(claimLabel(s.claim))}${s.original?quote(s.original):''}`+bubble(s.claim==='yes'?L('You think positive acceleration means moving forward. Choose a moment you think supports that idea, and keep it as evidence.'):s.claim==='no'?L('You think velocity matters too. Look for a moment with positive acceleration but no forward motion.'):L('Let’s observe first. Choose a moment that interests you and compare the signs of velocity and acceleration.'))+`<p class="small">${L('Move along the graph (above on mobile). Keep a moment that gives you something to talk about.')}</p><div id="selectedEvidence">${s.samples.length?evidenceAt(s.samples.at(-1).t):''}</div>${correction()}<div class="actions">${button('probe',L('Test my idea with this clue'))}</div>`;}
if(s.stage===2){const x=s.samples.at(-1),m=motion(x.t);let follow=x.t>3&&x.t<4?L('You found positive acceleration with negative velocity. Now focus on t = 3.5 minutes and separate direction from speed change.'):m.a>0&&m.v>0?L('Your moment has both positive velocity and positive acceleration. One supporting example cannot establish “always.” Let’s also look at t = 3.5 minutes.'):L('Keep this observation. To test “positive acceleration means forward,” let’s also examine t = 3.5 minutes.');html=evidenceAt(x.t)+bubble(follow)+`<div class="actions">${button('focus',L('Take me to 3.5 min'),'secondary')}</div><p class="prompt">${L('At t = 3.5 minutes specifically, how would you describe the motion?')}</p>`+checkForm('challenge');}
if(s.stage===3){html=bubble(L('A fresh ride: v(t) = 4 − t. At t = 3 minutes, how would you describe the motion?'))+`<div class="actions">${button('focus',L('Take me to 3 min'),'secondary')}</div><p class="small">${L('This is a new, near-transfer check. Learning and help from the previous question remain part of the session.')}</p>`+checkForm('transfer');}
if(s.stage===4){const g=grade(s.transfer,3,true);html=bubble(L('You’ve left a trail of evidence. There is no need to hide your first idea.'))+`<div class="summary-row"><h3>${L('01 / Where you started')}</h3>${quote(claimLabel(s.claim))}${s.original?quote(s.original):''}${s.correction?quote(s.correction):''}</div><div class="summary-row"><h3>${L('02 / What you actually tested')}</h3><p>${L(`You kept ${s.samples.length} ${s.samples.length===1?'moment':'moments'} and checked direction and speed at t = 3.5.`)}</p><p>${L('First choice')}: ${answerName(s.challenge)} · ${s.challenge.hinted?L('hint viewed before answering'):L('no question hint before answering')}</p>${s.challenge.reason?quote(s.challenge.reason):''}${s.challengeRevision?`<p class="mini-label">${L('LATER ADDITION / REVISION')}</p>${quote(s.challengeRevision)}`:''}</div><div class="summary-row"><h3>${L('03 / Evidence from a new case')}</h3><p>${L('First choice')}: ${answerName(s.transfer)}</p><p>${s.transfer.mode==='custom'?L('You responded to the new case in your own words. That text is not automatically graded; the reasoning still needs to be checked against the graph.'):g.direction&&g.speed?L('In the new case, both direction and speed-change choices match the model.'):L('Some choices in the new case need another look. Compare the sign of velocity and its distance from zero.')}</p><p>${s.transfer.hinted?L('A hint was viewed before this answer.'):L('No hint was opened before this answer; the previous question may still have helped.')}</p>${s.transfer.reason?quote(s.transfer.reason):''}${s.transferRevision?`<p class="mini-label">${L('LATER ADDITION / REVISION')}</p>${quote(s.transferRevision)}`:''}</div><div class="summary-row"><h3>${L('04 / What this does not yet establish')}</h3><p>${L('These choices do not establish mastery of the whole concept. More examples are needed to check understanding. Next, try a graph without numerical readouts: find an interval of backward motion with increasing speed and explain it.')}</p></div>${field('reflection',L('How would you put it now? You can leave a new question too.'),s.reflection)}<p class="small">${L('This is your reflection, not a conclusion rewritten on your behalf.')}</p><div class="actions">${button('download',L('Keep my exploration notes'))}${button('revisit',L('Revisit the new graph'),'secondary')}</div>`;}
$('dialogue').innerHTML=html;
if(s.stage===0){$('draft').oninput=e=>{s.draft=e.target.value;save();$('begin').disabled=!s.claim||(s.claim==='custom'&&!s.draft.trim());};$('initialOwn').onclick=()=>{s.claim='custom';save();render();$('draft').focus();};document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{s.claim=b.dataset.claim;save();render();});$('begin').disabled=!s.claim||(s.claim==='custom'&&!s.draft.trim());$('begin').onclick=()=>{s.original=s.draft;advance(1);};}
if(s.stage===1){bindText('correction','correction');$('probe').disabled=!s.samples.length;$('probe').onclick=()=>{s.t=3.5;advance(2);};}
if(s.stage===2||s.stage===3){const kind=s.stage===2?'challenge':'transfer';bindCheck(kind);$('focus').onclick=()=>{s.t=s.stage===2?3.5:3;save();graph();};}
if(s.stage===4){bindText('reflection','reflection');$('download').onclick=download;$('revisit').onclick=()=>{s.t=3;advance(3);};}
voice.attach();
if((s.stage===2||s.stage===3)){const kind=s.stage===2?'challenge':'transfer';if(s[kind])$('revision').previousElementSibling.before(voice.reviewBox({kind,answer:s[kind],revision:()=>s[kind+'Revision']||'',saved:s.aiReviews?.[kind]}));}
graph();samples();status();}
$('time').addEventListener('input',e=>{s.t=+e.target.value;graph();save();});$('graph').addEventListener('click',e=>{const svg=$('graph'),point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const p=point.matrixTransform(svg.getScreenCTM().inverse());s.t=Math.max(0,Math.min(5,Math.round((p.x-55)/100*20)/20));graph();save();});
$('capture').onclick=()=>{if(s.stage===3||s.samples.length>=20)return;s.samples.push({t:s.t,note:''});save();render();};
function download(){const lines=['# Quidence · Think in Motion',L('Guided dialogue prototype. Written explanations are not automatically graded.'),'',`Stage: ${s.stage+1}/5`,L('## Initial view'),claimLabel(s.claim),s.original||s.draft,L('## Clarification'),s.correction,L('## Original model and evidence'),'v(t)=(t−2)(t−4) m/s; t in minutes; a(t)=(2t−6)/60 m/s².',...s.samples.map(x=>`t=${x.t} min; v=${velocity(x.t)} m/s; a=${acceleration(x.t)} m/s²\n${x.note}`)];for(const k of ['challenge','transfer']){lines.push(`## ${k==='challenge'?'t=3.5, original model':'t=3, new model v(t)=4−t'}`);if(s[k]){lines.push(answerName(s[k]),s[k].reason,L('Later addition / revision:'),s[k+'Revision']||'',`Hint before answer: ${s[k].hinted}`,s[k].mode==='custom'?L('Own response: not automatically graded.'):`Numerical claims: direction ${grade(s[k],k==='challenge'?3.5:3,k==='transfer').direction?'matches':'needs review'}; speed ${grade(s[k],k==='challenge'?3.5:3,k==='transfer').speed?'matches':'needs review'}`);}else lines.push(L('Not submitted'));lines.push(`Hint or explanation opened during this question: ${s.hints.includes(k)}`);}lines.push(L('## My reflection'),s.reflection,L('## Limits'),'Choice checks are deterministic. Free text is preserved verbatim. No AI assessment is performed in this activity. No overall mastery score. Transfer follows prior learning and possible assistance.');if(s.voiceRecords?.length){lines.push('## Voice rehearsal notes (latest 20; typed and confirmed by the learner)',...s.voiceRecords.map(r=>`Stage ${r.context.stage+1}, t=${r.context.t}, field=${r.field}\nTyped rehearsal note: ${r.rawTranscript}\nConfirmed wording: ${r.confirmedTranscript}`));}
for(const [kind,r] of Object.entries(s.aiReviews||{}))lines.push(`## Optional AI follow-up / ${kind}`,`Confirmed text: ${r.request.text}\nGraph t=${r.request.t}`,`Quoted words: ${r.review.quote}`,r.review.observation,r.review.question,'Provisional AI interpretation, not a mastery assessment.');
const content=lines.join('\n\n');$('notesText').value=content;const previous=$('notesLink').getAttribute('href');if(previous)URL.revokeObjectURL(previous);$('notesLink').href=URL.createObjectURL(new Blob([content],{type:'text/markdown;charset=utf-8'}));$('notesDialog').showModal();}
const voice=installVoice({language:()=>lang,context:()=>({stage:s.stage,t:s.t,hinted:s.hints.includes(s.stage===3?'transfer':'challenge')}),onConfirmed:record=>{s.voiceRecords=[...(s.voiceRecords||[]),record];save();},onReview:(kind,record)=>{s.aiReviews={...s.aiReviews,[kind]:record};save();}});
$('closeNotes').onclick=()=>$('notesDialog').close();
$('export').onclick=download;$('reset').onclick=()=>$('resetDialog').showModal();$('cancelReset').onclick=()=>$('resetDialog').close();$('confirmReset').onclick=()=>{s=initial();ephemeral={direction:'',speed:''};try{localStorage.removeItem(KEY);lastRaw=null;blocked=false;storageIssue=false;}catch{storageIssue=true;}save();$('resetDialog').close();render();};render();
